package cn.zhuatech.forecast.controller; import cn.zhuatech.forecast.common.ApiResponse; import cn.zhuatech.forecast.dto.ForecastDto.*; import cn.zhuatech.forecast.service.ForecastService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final ForecastService service;public OperationsAdminController(ForecastService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
